insert into public.courses(id,level,title,description,position) values('a1','A1','A1 Temelleri','Selamlaşma, tanışma, artikel, sein/haben ve Präsens.',1) on conflict (id) do update set title=excluded.title,description=excluded.description;
insert into public.courses(id,level,title,description,position) values('a2','A2','A2 Gelişim','Perfekt, Dativ ve Nebensätze.',2) on conflict (id) do update set title=excluded.title,description=excluded.description;
insert into public.lessons(id,course_id,level,title,intro_tr,points,examples,position) values('a1-begruessung','a1','A1','Hallo und Begrüßung','Almanca''da selamlaşma günün saatine ve resmiyet derecesine göre değişir.','["Hallo ve Hi gayriresmîdir; Guten Tag resmî ortamlarda kullanılır.", "Sabah Guten Morgen, akşam Guten Abend denir.", "Tschüs gayriresmî, Auf Wiedersehen resmî vedalaşmadır.", "Wie geht''s? ''Nasılsın?'' demektir; kısa cevap: Danke, gut."]'::jsonb,'[{"de": "Guten Morgen, Frau Müller!", "tr": "Günaydın Bayan Müller!"}, {"de": "Wie geht es Ihnen? – Danke, gut.", "tr": "Nasılsınız? – Teşekkürler, iyi."}, {"de": "Tschüs, bis morgen!", "tr": "Hoşça kal, yarın görüşürüz!"}]'::jsonb,1) on conflict (id) do update set title=excluded.title,intro_tr=excluded.intro_tr,points=excluded.points,examples=excluded.examples;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a1-begruessung-q1','grammatik','A1','Du triffst deinen Lehrer um 9 Uhr morgens. Was sagst du?','["Guten Morgen", "Gute Nacht", "Tschüs", "Guten Abend"]'::jsonb,'Guten Morgen','Sabah saatlerinde Guten Morgen denir.','a1-begruessung') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a1-begruessung-q2','grammatik','A1','Welche Verabschiedung ist formell?','["Tschüs", "Auf Wiedersehen", "Hi", "Hallo"]'::jsonb,'Auf Wiedersehen','Auf Wiedersehen resmî vedalaşmadır.','a1-begruessung') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a1-begruessung-q3','grammatik','A1','Auf „Wie geht''s?“ antwortest du:','["Danke, gut.", "Ich heiße Anna.", "Auf Wiedersehen.", "Ich bin 20."]'::jsonb,'Danke, gut.','Wie geht''s? sorusuna durum bildiren kısa cevap verilir.','a1-begruessung') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.lessons(id,course_id,level,title,intro_tr,points,examples,position) values('a1-vorstellen','a1','A1','Sich vorstellen','Kendini tanıtırken sabit kalıplar kullanılır.','["Ich heiße … veya Mein Name ist … ile isim söylenir.", "Ich komme aus … ile ülke/şehir belirtilir.", "Ich wohne in … yaşadığın yeri anlatır.", "Ich bin … Jahre alt yaşı söyler."]'::jsonb,'[{"de": "Ich heiße Ali und ich komme aus der Türkei.", "tr": "Adım Ali ve Türkiye''denim."}, {"de": "Ich wohne in Istanbul.", "tr": "İstanbul''da oturuyorum."}, {"de": "Ich bin 25 Jahre alt.", "tr": "25 yaşındayım."}]'::jsonb,2) on conflict (id) do update set title=excluded.title,intro_tr=excluded.intro_tr,points=excluded.points,examples=excluded.examples;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a1-vorstellen-q1','grammatik','A1','Ich ___ Ali.','["heiße", "heißt", "heißen", "heißst"]'::jsonb,'heiße','ich ile fiil heiße şeklinde çekimlenir.','a1-vorstellen') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a1-vorstellen-q2','grammatik','A1','Woher kommst du?','["Ich komme aus Izmir.", "Ich wohne gern.", "Ich bin gut.", "Ich heiße komme."]'::jsonb,'Ich komme aus Izmir.','Woher? sorusu geldiğin yeri sorar.','a1-vorstellen') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a1-vorstellen-q3','grammatik','A1','Ich ___ 25 Jahre alt.','["bin", "habe", "heiße", "komme"]'::jsonb,'bin','Almanca''da yaş sein fiiliyle söylenir: Ich bin … Jahre alt.','a1-vorstellen') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.lessons(id,course_id,level,title,intro_tr,points,examples,position) values('a1-artikel','a1','A1','Artikel: der, die, das','Her Almanca ismin bir cinsiyeti vardır ve artikel isimle birlikte öğrenilmelidir.','["der eril, die dişil, das nötr isimlerle kullanılır.", "Çoğulda artikel her zaman die olur.", "Belirsiz artikel: ein (der/das), eine (die).", "Cinsiyet çoğu zaman mantıkla tahmin edilemez; kelimeyi artikeliyle ezberle."]'::jsonb,'[{"de": "der Tisch – die Lampe – das Buch", "tr": "masa – lamba – kitap"}, {"de": "Die Kinder spielen im Garten.", "tr": "Çocuklar bahçede oynuyor."}, {"de": "Das ist eine Lampe.", "tr": "Bu bir lamba."}]'::jsonb,3) on conflict (id) do update set title=excluded.title,intro_tr=excluded.intro_tr,points=excluded.points,examples=excluded.examples;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a1-artikel-q1','grammatik','A1','___ Buch ist neu.','["Das", "Der", "Die", "Den"]'::jsonb,'Das','Buch nötr bir isimdir: das Buch.','a1-artikel') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a1-artikel-q2','grammatik','A1','___ Lampe ist hell.','["Die", "Der", "Das", "Ein"]'::jsonb,'Die','Lampe dişildir: die Lampe.','a1-artikel') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a1-artikel-q3','grammatik','A1','Im Plural benutzt man immer: ___ Kinder.','["Die", "Der", "Das", "Ein"]'::jsonb,'Die','Çoğulda artikel hep die''dir.','a1-artikel') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.lessons(id,course_id,level,title,intro_tr,points,examples,position) values('a1-sein-haben','a1','A1','Sein und haben','İki en önemli yardımcı fiil: sein (olmak) ve haben (sahip olmak).','["sein: ich bin, du bist, er/sie/es ist, wir sind, ihr seid, sie sind.", "haben: ich habe, du hast, er/sie/es hat, wir haben, ihr habt, sie haben.", "sein durum/meslek bildirir, haben sahip olmayı anlatır.", "Olumsuzluk: sein ile nicht, haben + isim ile kein kullanılır."]'::jsonb,'[{"de": "Ich bin Student.", "tr": "Ben öğrenciyim."}, {"de": "Er hat einen Bruder.", "tr": "Onun bir erkek kardeşi var."}, {"de": "Wir sind müde.", "tr": "Biz yorgunuz."}]'::jsonb,4) on conflict (id) do update set title=excluded.title,intro_tr=excluded.intro_tr,points=excluded.points,examples=excluded.examples;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a1-sein-haben-q1','grammatik','A1','Du ___ sehr nett.','["bist", "bin", "ist", "seid"]'::jsonb,'bist','du ile sein: du bist.','a1-sein-haben') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a1-sein-haben-q2','grammatik','A1','Sie (o) ___ zwei Kinder.','["hat", "habe", "hast", "haben"]'::jsonb,'hat','sie (tekil) ile haben: sie hat.','a1-sein-haben') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a1-sein-haben-q3','grammatik','A1','Wir ___ Hunger.','["haben", "sind", "habt", "hat"]'::jsonb,'haben','Hunger haben kalıbı: wir haben Hunger.','a1-sein-haben') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.lessons(id,course_id,level,title,intro_tr,points,examples,position) values('a1-praesens','a1','A1','Präsens: Regelmäßige Verben','Düzenli fiiller kök + kişi eki ile çekimlenir.','["Ekler: -e, -st, -t, -en, -t, -en (ich, du, er, wir, ihr, sie).", "wohnen → ich wohne, du wohnst, er wohnt.", "Fiil, düz cümlede ikinci sırada durur.", "Evet/hayır sorusunda fiil en başa gelir: Wohnst du hier?"]'::jsonb,'[{"de": "Ich lerne jeden Tag Deutsch.", "tr": "Her gün Almanca öğreniyorum."}, {"de": "Er wohnt in Berlin.", "tr": "O Berlin''de oturuyor."}, {"de": "Trinkst du Kaffee?", "tr": "Kahve içiyor musun?"}]'::jsonb,5) on conflict (id) do update set title=excluded.title,intro_tr=excluded.intro_tr,points=excluded.points,examples=excluded.examples;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a1-praesens-q1','grammatik','A1','Er ___ in Berlin. (wohnen)','["wohnt", "wohne", "wohnst", "wohnen"]'::jsonb,'wohnt','er ile fiil -t eki alır.','a1-praesens') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a1-praesens-q2','grammatik','A1','Wir ___ Deutsch. (lernen)','["lernen", "lernt", "lerne", "lernst"]'::jsonb,'lernen','wir ile fiil mastar gibi çekimlenir: lernen.','a1-praesens') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a1-praesens-q3','grammatik','A1','___ du Kaffee? (trinken)','["Trinkst", "Trinke", "Trinkt", "Trinken"]'::jsonb,'Trinkst','du ile -st eki gelir ve soruda fiil başa geçer.','a1-praesens') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.lessons(id,course_id,level,title,intro_tr,points,examples,position) values('a1-zahlen-uhrzeit','a1','A1','Zahlen und Uhrzeit','Sayıları ve saati söylemek günlük hayatın temelidir.','["1 eins, 2 zwei, 3 drei, 4 vier, 5 fünf, 6 sechs, 7 sieben, 8 acht, 9 neun, 10 zehn.", "Saat sorusu: Wie spät ist es? veya Wie viel Uhr ist es?", "Es ist drei Uhr. = Saat üç.", "halb vier = 3:30 (Almanca''da ''dörde yarım kala'' denir)."]'::jsonb,'[{"de": "Es ist neun Uhr.", "tr": "Saat dokuz."}, {"de": "Es ist halb vier.", "tr": "Saat üç buçuk."}, {"de": "Ich habe zwei Brüder.", "tr": "İki erkek kardeşim var."}]'::jsonb,6) on conflict (id) do update set title=excluded.title,intro_tr=excluded.intro_tr,points=excluded.points,examples=excluded.examples;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a1-zahlen-uhrzeit-q1','grammatik','A1','Wie sagt man die Zahl 7?','["sieben", "sechs", "acht", "neun"]'::jsonb,'sieben','7 = sieben.','a1-zahlen-uhrzeit') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a1-zahlen-uhrzeit-q2','grammatik','A1','„halb vier“ bedeutet:','["3:30", "4:30", "3:45", "4:15"]'::jsonb,'3:30','halb vier = dörde yarım kala = 3:30.','a1-zahlen-uhrzeit') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a1-zahlen-uhrzeit-q3','grammatik','A1','Es ist ___ Uhr. (9)','["neun", "nein", "neu", "acht"]'::jsonb,'neun','9 = neun.','a1-zahlen-uhrzeit') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.lessons(id,course_id,level,title,intro_tr,points,examples,position) values('a2-perfekt','a2','A2','Perfekt','Geçmişi konuşma dilinde en sık Perfekt ile anlatırız.','["Perfekt = haben/sein (Präsens) + Partizip II.", "Çoğu fiil haben ile; hareket ve durum değişikliği (gehen, fahren, bleiben) sein ile kurulur.", "Düzenli fiil: ge-…-t (machen → gemacht).", "Partizip II cümlenin sonuna gider."]'::jsonb,'[{"de": "Ich habe Deutsch gelernt.", "tr": "Almanca öğrendim."}, {"de": "Er ist nach Berlin gefahren.", "tr": "O Berlin''e gitti (araçla)."}, {"de": "Wir haben Pizza gegessen.", "tr": "Pizza yedik."}]'::jsonb,7) on conflict (id) do update set title=excluded.title,intro_tr=excluded.intro_tr,points=excluded.points,examples=excluded.examples;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a2-perfekt-q1','grammatik','A2','Gestern ___ ich ins Kino gegangen.','["bin", "habe", "hat", "wurde"]'::jsonb,'bin','gehen hareket fiilidir ve sein ile kurulur.','a2-perfekt') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a2-perfekt-q2','grammatik','A2','Sie hat einen Brief ___.','["geschrieben", "schreibt", "schrieb", "schreiben"]'::jsonb,'geschrieben','schreiben fiilinin Partizip II''si geschrieben''dir.','a2-perfekt') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a2-perfekt-q3','grammatik','A2','Partizip II von „machen“:','["gemacht", "gemachen", "gemachten", "macht"]'::jsonb,'gemacht','Düzenli fiil: ge-mach-t.','a2-perfekt') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.lessons(id,course_id,level,title,intro_tr,points,examples,position) values('a2-dativ','a2','A2','Dativ','Dativ ''kime/neye'' sorusunun cevabıdır ve bazı edatlarla zorunlu kullanılır.','["Dativ artikelleri: dem (der/das), der (die), den + -n (çoğul).", "mit, bei, nach, von, zu, aus, seit her zaman Dativ ister.", "helfen, danken, gehören gibi fiiller Dativ ile kullanılır.", "zu + dem = zum, zu + der = zur."]'::jsonb,'[{"de": "Ich helfe dem Kind.", "tr": "Çocuğa yardım ediyorum."}, {"de": "Sie fährt mit dem Bus.", "tr": "O otobüsle gidiyor."}, {"de": "Wir gehen zur Ärztin.", "tr": "Doktora (kadın) gidiyoruz."}]'::jsonb,8) on conflict (id) do update set title=excluded.title,intro_tr=excluded.intro_tr,points=excluded.points,examples=excluded.examples;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a2-dativ-q1','grammatik','A2','Ich fahre mit ___ Bus.','["dem", "den", "der", "das"]'::jsonb,'dem','mit Dativ ister; der Bus → dem Bus.','a2-dativ') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a2-dativ-q2','grammatik','A2','Er hilft ___ Frau.','["der", "die", "dem", "den"]'::jsonb,'der','helfen Dativ ister; die Frau → der Frau.','a2-dativ') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a2-dativ-q3','grammatik','A2','Ich wohne bei ___ Eltern.','["meinen", "meine", "meiner", "meinem"]'::jsonb,'meinen','Çoğul Dativ: bei meinen Eltern.','a2-dativ') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.lessons(id,course_id,level,title,intro_tr,points,examples,position) values('a2-weil','a2','A2','Nebensätze mit weil und dass','weil ve dass ile yan cümle kurulduğunda fiil cümlenin sonuna gider.','["weil = çünkü; fiil yan cümlenin sonuna gider.", "dass = ki/-diğini; fiil yine sonda durur.", "Ana cümle ile yan cümle virgülle ayrılır.", "Ich bleibe zu Hause, weil ich krank bin."]'::jsonb,'[{"de": "Ich lerne Deutsch, weil ich in Deutschland arbeiten will.", "tr": "Almanya''da çalışmak istediğim için Almanca öğreniyorum."}, {"de": "Er sagt, dass er müde ist.", "tr": "Yorgun olduğunu söylüyor."}, {"de": "Sie lacht, weil der Film lustig ist.", "tr": "Film komik olduğu için gülüyor."}]'::jsonb,9) on conflict (id) do update set title=excluded.title,intro_tr=excluded.intro_tr,points=excluded.points,examples=excluded.examples;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a2-weil-q1','grammatik','A2','Ich lerne Deutsch, weil ich in Deutschland ___.','["arbeiten will", "will arbeiten", "arbeite will", "arbeiten wollen"]'::jsonb,'arbeiten will','weil cümlesinde çekimli fiil (will) en sona gider.','a2-weil') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a2-weil-q2','grammatik','A2','Er sagt, ___ er müde ist.','["dass", "weil", "ob wie", "und"]'::jsonb,'dass','''Dediğini'' bildiren yan cümle dass ile kurulur.','a2-weil') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,lesson_id) values('a2-weil-q3','grammatik','A2','Ich bleibe hier, weil es ___.','["regnet", "regnen es", "es regnet", "regnest"]'::jsonb,'regnet','weil es regnet: fiil en sonda.','a2-weil') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.grammar_topics(id,level,title,explanation_tr,comparisons,position) values('g-artikel','A1','Artikel','Almanca''da isimlerin üç cinsiyeti vardır: der (eril), die (dişil), das (nötr). Çoğulda hepsi die olur. Artikeli ismin parçası gibi ezberle.','[{"wrong": "Das Tisch ist braun.", "right": "Der Tisch ist braun.", "why": "Tisch erildir."}]'::jsonb,1) on conflict (id) do update set explanation_tr=excluded.explanation_tr,comparisons=excluded.comparisons;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,grammar_id) values('g-artikel-q1','grammatik','A1','___ Tisch ist braun.','["Der", "Die", "Das", "Den"]'::jsonb,'Der','Tisch eril: der Tisch.','g-artikel') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,grammar_id) values('g-artikel-q2','grammatik','A1','Das ist ___ Lampe.','["eine", "ein", "einen", "einem"]'::jsonb,'eine','Lampe dişil: eine Lampe.','g-artikel') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.grammar_topics(id,level,title,explanation_tr,comparisons,position) values('g-sein-haben','A1','Sein und haben','sein ''olmak'', haben ''sahip olmak'' demektir. İkisi de düzensiz çekimlenir ve Perfekt''te yardımcı fiil olarak kullanılır.','[{"wrong": "Ich habe müde.", "right": "Ich bin müde.", "why": "Yorgunluk durumu sein ile söylenir."}]'::jsonb,2) on conflict (id) do update set explanation_tr=excluded.explanation_tr,comparisons=excluded.comparisons;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,grammar_id) values('g-sein-haben-q1','grammatik','A1','Ich ___ müde.','["bin", "habe", "hat", "ist"]'::jsonb,'bin','Durum bildirmek için sein kullanılır.','g-sein-haben') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,grammar_id) values('g-sein-haben-q2','grammatik','A1','Er ___ ein Auto.','["hat", "ist", "hast", "haben"]'::jsonb,'hat','Sahiplik için haben: er hat.','g-sein-haben') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.grammar_topics(id,level,title,explanation_tr,comparisons,position) values('g-praesens','A1','Präsens','Düzenli fiiller kök + -e, -st, -t, -en, -t, -en ile çekimlenir. Ayrılabilen fiillerde ön ek cümle sonuna gider.','[{"wrong": "Ich gehen Schule.", "right": "Ich gehe zur Schule.", "why": "ich ile fiil -e alır ve ''okula'' için zur kullanılır."}]'::jsonb,3) on conflict (id) do update set explanation_tr=excluded.explanation_tr,comparisons=excluded.comparisons;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,grammar_id) values('g-praesens-q1','grammatik','A1','Sie ___ jeden Tag Zeitung. (lesen)','["liest", "lest", "lese", "lesen"]'::jsonb,'liest','lesen düzensizdir: sie liest.','g-praesens') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,grammar_id) values('g-praesens-q2','grammatik','A1','Ich ___ um 7 Uhr auf. (aufstehen)','["stehe", "steht", "stehst", "aufstehe"]'::jsonb,'stehe','Ayrılabilen fiilde ''auf'' sona gider: Ich stehe um 7 Uhr auf.','g-praesens') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.grammar_topics(id,level,title,explanation_tr,comparisons,position) values('g-perfekt','A2','Perfekt','Perfekt = haben/sein + Partizip II. Hareket ve durum değişikliği bildiren fiiller sein alır.','[{"wrong": "Ich habe nach Berlin gefahren.", "right": "Ich bin nach Berlin gefahren.", "why": "fahren hareket fiili olduğu için sein alır."}]'::jsonb,4) on conflict (id) do update set explanation_tr=excluded.explanation_tr,comparisons=excluded.comparisons;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,grammar_id) values('g-perfekt-q1','grammatik','A2','Er hat das Fenster ___.','["geöffnet", "öffnet", "geöffnen", "öffnen"]'::jsonb,'geöffnet','öffnen düzenli fiildir: geöffnet.','g-perfekt') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,grammar_id) values('g-perfekt-q2','grammatik','A2','Wir ___ nach Hause gefahren.','["sind", "haben", "waren", "wurden"]'::jsonb,'sind','fahren hareket fiili: sein.','g-perfekt') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.grammar_topics(id,level,title,explanation_tr,comparisons,position) values('g-dativ','A2','Dativ','Dativ kime/neye sorusunu cevaplar. mit, bei, nach, von, zu, aus, seit edatlarından sonra ve helfen, danken, gehören fiilleriyle kullanılır.','[{"wrong": "Ich helfe das Kind.", "right": "Ich helfe dem Kind.", "why": "helfen Dativ ister."}]'::jsonb,5) on conflict (id) do update set explanation_tr=excluded.explanation_tr,comparisons=excluded.comparisons;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,grammar_id) values('g-dativ-q1','grammatik','A2','Ich danke ___ Lehrerin.','["der", "die", "dem", "den"]'::jsonb,'der','danken Dativ ister; die Lehrerin → der Lehrerin.','g-dativ') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,grammar_id) values('g-dativ-q2','grammatik','A2','Das Buch gehört ___ Kind.','["dem", "das", "der", "den"]'::jsonb,'dem','gehören Dativ ister; das Kind → dem Kind.','g-dativ') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.grammar_topics(id,level,title,explanation_tr,comparisons,position) values('g-nebensatz','A2','Nebensätze','weil, dass, wenn gibi bağlaçlardan sonra çekimli fiil cümlenin sonuna gider.','[{"wrong": "Ich bleibe, weil ich bin krank.", "right": "Ich bleibe, weil ich krank bin.", "why": "weil cümlesinde fiil sondadır."}]'::jsonb,6) on conflict (id) do update set explanation_tr=excluded.explanation_tr,comparisons=excluded.comparisons;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,grammar_id) values('g-nebensatz-q1','grammatik','A2','Ich weiß, dass er morgen ___.','["kommt", "kommen er", "er kommt", "kommst"]'::jsonb,'kommt','dass cümlesinde fiil sonda ve er ile kommt.','g-nebensatz') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.exercises(id,skill,level,prompt,options,answer,explanation,grammar_id) values('g-nebensatz-q2','grammatik','A2','Sie lacht, weil der Film lustig ___.','["ist", "sind", "bin", "wird"]'::jsonb,'ist','weil cümlesinde fiil sona gider: lustig ist.','g-nebensatz') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
