insert into public.exercises(id,skill,level,grp,passage,audio_text,prompt,options,answer,explanation) values('pool-17','lesen','A1','les-a1-1','Hallo, ich bin Lena. Ich bin 22 Jahre alt und wohne in Hamburg. Ich studiere Medizin. Am Wochenende spiele ich gern Fußball.',null,'Wo wohnt Lena?','["In Hamburg", "In Berlin", "In München", "In Wien"]'::jsonb,'In Hamburg','Metinde: wohne in Hamburg.') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,passage=excluded.passage,audio_text=excluded.audio_text;
