insert into public.exercises(id,skill,level,grp,passage,audio_text,prompt,options,answer,explanation) values('pool-19','lesen','A1','les-a1-2','Liebe Anna, morgen habe ich Geburtstag. Die Party beginnt um 18 Uhr bei mir zu Hause. Bitte bring einen Kuchen mit. Viele Grüße, Tom',null,'Wann beginnt die Party?','["Um 18 Uhr", "Um 8 Uhr", "Um 16 Uhr", "Morgen Mittag"]'::jsonb,'Um 18 Uhr','Metinde: Die Party beginnt um 18 Uhr.') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,passage=excluded.passage,audio_text=excluded.audio_text;
insert into public.exercises(id,skill,level,grp,passage,audio_text,prompt,options,answer,explanation) values('pool-20','lesen','A1','les-a1-2','Liebe Anna, morgen habe ich Geburtstag. Die Party beginnt um 18 Uhr bei mir zu Hause. Bitte bring einen Kuchen mit. Viele Grüße, Tom',null,'Was soll Anna mitbringen?','["Einen Kuchen", "Getränke", "Blumen", "Musik"]'::jsonb,'Einen Kuchen','Metinde: Bitte bring einen Kuchen mit.') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,passage=excluded.passage,audio_text=excluded.audio_text;
insert into public.exercises(id,skill,level,grp,passage,audio_text,prompt,options,answer,explanation) values('pool-21','lesen','A2','les-a2-1','Sehr geehrte Frau Becker, leider kann ich am Dienstag nicht zum Termin kommen, weil mein Sohn krank ist. Könnten wir den Termin auf Donnerstag verschieben? Mit freundlichen Grüßen, Karin Yilmaz',null,'Warum kann Frau Yilmaz nicht kommen?','["Ihr Sohn ist krank.", "Sie hat Urlaub.", "Sie muss arbeiten.", "Sie hat den Termin vergessen."]'::jsonb,'Ihr Sohn ist krank.','Metinde: weil mein Sohn krank ist.') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,passage=excluded.passage,audio_text=excluded.audio_text;
insert into public.exercises(id,skill,level,grp,passage,audio_text,prompt,options,answer,explanation) values('pool-22','lesen','A2','les-a2-1','Sehr geehrte Frau Becker, leider kann ich am Dienstag nicht zum Termin kommen, weil mein Sohn krank ist. Könnten wir den Termin auf Donnerstag verschieben? Mit freundlichen Grüßen, Karin Yilmaz',null,'Wann möchte sie einen neuen Termin?','["Am Donnerstag", "Am Dienstag", "Am Freitag", "Am Montag"]'::jsonb,'Am Donnerstag','Metinde: den Termin auf Donnerstag verschieben.') on conflict (id) do update set prompt=excluded.prompt,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,passage=excluded.passage,audio_text=excluded.audio_text;
